<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'
import { courseCatalog, knowledgeSubjects, practiceQuestions } from '@/mock/data'
import { api, token, selectedExamId, showApiError } from '@/services/api'
import { backOrFallback } from '@/utils/navigation'
import { getFavoriteRecords, removeFavorites as removeFavoriteRecords, type FavoriteRecord, type FavoriteType } from '@/utils/favorites'
import { useAppStore } from '@/store/app'
import { migrateLegacyNotes, removeNotes, type NoteRecord, type NoteSourceType } from '@/utils/notes'

const mode = ref((uni.getStorageSync('sxb-practice-tool-mode') || 'wrong') as 'wrong' | 'favorite' | 'note')
const tabLabels = [{ key: 'wrong', label: '错题本', icon: 'refresh' }, { key: 'favorite', label: '收藏', icon: 'star' }, { key: 'note', label: '笔记', icon: 'compose' }] as const
const tabColors = { wrong: '#e17832', favorite: '#7655df', note: '#1a9a7b' } as const
const { exam } = useAppStore()
const storedWrong = ref<string[]>(uni.getStorageSync('sxb-wrong-questions') || [])
const clearWrongVisible = ref(false)
const visibleWrongCount = ref(12)
type FavoriteFilter = 'all' | FavoriteType
const favoriteFilter = ref<FavoriteFilter>('all')
const manageFavorites = ref(false)
const selectedFavoriteIds = ref<string[]>([])
const cancelFavoriteVisible = ref(false)
const visibleFavoriteCount = ref(12)
const favoriteTypeLabels: Record<FavoriteFilter, string> = { all: '全部', knowledge: '知识点', course: '精讲课', question: '题目' }
const storedFavorites = ref<FavoriteRecord[]>(getFavoriteRecords())
type NoteFilter = 'all' | NoteSourceType
const noteFilter = ref<NoteFilter>('all')
const manageNotes = ref(false)
const selectedNoteIds = ref<string[]>([])
const deleteNotesVisible = ref(false)
const visibleNoteCount = ref(12)
const noteTypeLabels: Record<NoteFilter, string> = { all: '全部', question: '题目', knowledge: '知识点', course: '精讲课' }
const readAiReviewQuota = () => {
  const saved = uni.getStorageSync('sxb-ai-review-quota')
  return saved === '' || saved === null || saved === undefined ? 0 : Number(saved)
}
const aiReviewQuota = ref(readAiReviewQuota())
const noteSources = [
  ...practiceQuestions.map(item => ({ sourceId: item.id, sourceType: 'question' as const })),
  ...knowledgeSubjects.flatMap(subject => subject.chapters.flatMap(chapter => chapter.sections.flatMap(section => section.points.map(point => ({ sourceId: point.id, sourceType: 'knowledge' as const }))))),
  ...courseCatalog.map(item => ({ sourceId: item.id, sourceType: 'course' as const })),
]
const storedNotes = ref<NoteRecord[]>(migrateLegacyNotes(noteSources))
const questions = computed(() => practiceQuestions.filter(item => storedWrong.value.includes(item.id)))
const visibleWrongQuestions = computed(() => questions.value.slice(0, visibleWrongCount.value))
const hasMoreWrongQuestions = computed(() => visibleWrongCount.value < questions.value.length)
const subjectShortName = (subjectId: string) => subjectId === 'practice' ? '初级实务' : '初级综合'
const favoriteItems = computed(() => storedFavorites.value.slice().sort((a, b) => b.createdAt - a.createdAt).map(record => {
  const { id } = record
  const question = practiceQuestions.find(item => item.id === id)
  if (question) return { ...record, typeLabel: '题目', title: question.stem, meta: `${question.typeName} · ${question.year}年真题`, icon: 'list', color: '#3569e8' }
  const course = courseCatalog.find(item => item.id === id)
  if (course) return { ...record, typeLabel: '精讲课', title: `第${course.sectionNo}节 ${course.sectionName}`, meta: `${course.typeName} · 共${course.totalMinutes}分钟`, icon: 'sound', color: '#e98a3a' }
  const point = knowledgeSubjects.flatMap(subject => subject.chapters.flatMap(chapter => chapter.sections.flatMap(section => section.points))).find(item => item.id === id)
  return point ? { ...record, typeLabel: '知识点', title: point.title, meta: `${point.stars}星 · 掌握${point.mastery}%`, icon: 'map', color: '#7655df' } : null
}).filter((item): item is NonNullable<typeof item> => Boolean(item)))
const filteredFavorites = computed(() => favoriteItems.value.filter(item => favoriteFilter.value === 'all' || item.type === favoriteFilter.value))
const visibleFavorites = computed(() => filteredFavorites.value.slice(0, visibleFavoriteCount.value))
const hasMoreFavorites = computed(() => visibleFavoriteCount.value < filteredFavorites.value.length)
const noteItems = computed(() => storedNotes.value.slice().sort((a, b) => b.updatedAt - a.updatedAt).map(note => {
  const question = practiceQuestions.find(item => item.id === note.sourceId)
  if (question) return { ...note, typeLabel: '题目', title: question.stem, meta: `${question.typeName} · ${subjectShortName(question.subjectId)} · ${question.knowledgePointTitle}`, icon: 'list' }
  const course = courseCatalog.find(item => item.id === note.sourceId)
  if (course) return { ...note, typeLabel: '精讲课', title: `第${course.sectionNo}节 ${course.sectionName}`, meta: `${course.typeName} · ${subjectShortName(course.subjectId)} · ${course.chapterName}`, icon: 'sound' }
  const point = knowledgeSubjects.flatMap(subject => subject.chapters.flatMap(chapter => chapter.sections.flatMap(section => section.points.map(item => ({ item, subject, chapter }))))).find(record => record.item.id === note.sourceId)
  return point ? { ...note, typeLabel: '知识点', title: point.item.title, meta: `${subjectShortName(point.subject.id)} · 第${point.chapter.no}章 · ${point.item.stars}星`, icon: 'map' } : null
}).filter((item): item is NonNullable<typeof item> => Boolean(item)))
const filteredNotes = computed(() => noteItems.value.filter(item => noteFilter.value === 'all' || item.sourceType === noteFilter.value))
const visibleNotes = computed(() => filteredNotes.value.slice(0, visibleNoteCount.value))
const hasMoreNotes = computed(() => visibleNoteCount.value < filteredNotes.value.length)
onLoad((options?: Record<string, string>) => { if (options?.mode === 'wrong' || options?.mode === 'favorite' || options?.mode === 'note') mode.value = options.mode })
onShow(() => {
  const restoreMode = uni.getStorageSync('sxb-practice-tool-return-mode')
  if (restoreMode === 'wrong' || restoreMode === 'favorite' || restoreMode === 'note') {
    mode.value = restoreMode
    uni.setStorageSync('sxb-practice-tool-mode', restoreMode)
    uni.removeStorageSync('sxb-practice-tool-return-mode')
  }
  storedWrong.value = uni.getStorageSync('sxb-wrong-questions') || []
  storedFavorites.value = getFavoriteRecords()
  storedNotes.value = migrateLegacyNotes(noteSources)
  aiReviewQuota.value = 0
  if(token())void api(`/review/${selectedExamId()}`).then(r=>{aiReviewQuota.value=r.remaining}).catch(showApiError)
})
const setMode = (next: typeof mode.value) => { mode.value = next; uni.setStorageSync('sxb-practice-tool-mode', next) }
const setFavoriteFilter = (next: FavoriteFilter) => { favoriteFilter.value = next; visibleFavoriteCount.value = 12; selectedFavoriteIds.value = [] }
const toggleFavoriteSelection = (id: string) => { selectedFavoriteIds.value = selectedFavoriteIds.value.includes(id) ? selectedFavoriteIds.value.filter(item => item !== id) : [...selectedFavoriteIds.value, id] }
const toggleSelectAll = () => { selectedFavoriteIds.value = selectedFavoriteIds.value.length === visibleFavorites.value.length ? [] : visibleFavorites.value.map(item => item.id) }
const removeFavorites = async (ids: string[]) => { storedFavorites.value = await removeFavoriteRecords(ids); selectedFavoriteIds.value = []; uni.showToast({ title: `已取消${ids.length}条收藏`, icon: 'none' }) }
const removeFavorite = (id: string) => removeFavorites([id])
const batchRemoveFavorites = () => {
  if (!selectedFavoriteIds.value.length) return uni.showToast({ title: '请先选择收藏内容', icon: 'none' })
  cancelFavoriteVisible.value = true
}
const confirmBatchRemoveFavorites = () => {
  const ids = [...selectedFavoriteIds.value]
  cancelFavoriteVisible.value = false
  if (ids.length) removeFavorites(ids)
}
const loadMoreFavorites = () => { visibleFavoriteCount.value += 12 }
const openFavorite = (item: { id: string; type: FavoriteType }) => {
  if (manageFavorites.value) return toggleFavoriteSelection(item.id)
  if (item.type === 'question') return uni.navigateTo({ url: `/pages/practice-session/index?questionId=${encodeURIComponent(item.id)}&mode=favorite&returnUrl=${encodeURIComponent('/pages/practice-tools/index?mode=favorite')}` })
  if (item.type === 'course') return uni.navigateTo({ url: `/pages/course-detail/index?id=${encodeURIComponent(item.id)}` })
  return uni.navigateTo({ url: `/pages/knowledge-detail/index?id=${encodeURIComponent(item.id)}` })
}
const clearWrong = async () => {
  try {
    await api(`/wrong/${selectedExamId()}`,'DELETE')
    storedWrong.value = []
    visibleWrongCount.value = 12
    clearWrongVisible.value = false
    uni.setStorageSync('sxb-wrong-questions', [])
    uni.showToast({ title: '错题本已清空，学习记录保留', icon: 'none' })
  }catch(error){showApiError(error)}
}
const reviewWrongQuestions = () => {
  if (!questions.value.length) return uni.showToast({ title: '当前没有需要复习的错题', icon: 'none' })
  uni.navigateTo({ url: `/pages/practice-session/index?mode=wrong&returnUrl=${encodeURIComponent('/pages/practice-tools/index?mode=wrong')}` })
}
const loadMoreWrongQuestions = () => { visibleWrongCount.value += 12 }
const setNoteFilter = (next: NoteFilter) => { noteFilter.value = next; visibleNoteCount.value = 12; selectedNoteIds.value = [] }
const toggleNoteSelection = (id: string) => { selectedNoteIds.value = selectedNoteIds.value.includes(id) ? selectedNoteIds.value.filter(item => item !== id) : [...selectedNoteIds.value, id] }
const toggleSelectAllNotes = () => { selectedNoteIds.value = selectedNoteIds.value.length === visibleNotes.value.length ? [] : visibleNotes.value.map(item => item.id) }
const requestDeleteNotes = () => {
  if (!selectedNoteIds.value.length) return uni.showToast({ title: '请先选择要删除的笔记', icon: 'none' })
  deleteNotesVisible.value = true
}
const confirmDeleteNotes = async () => { storedNotes.value = await removeNotes(selectedNoteIds.value); selectedNoteIds.value = []; deleteNotesVisible.value = false; uni.showToast({ title: '笔记已删除', icon: 'none' }) }
const openNoteDetail = (id: string) => manageNotes.value ? toggleNoteSelection(id) : uni.navigateTo({ url: `/pages/note-detail/index?id=${encodeURIComponent(id)}` })
const openAiReview = () => {
  uni.setStorageSync('sxb-practice-tool-return-mode', 'note')
  uni.navigateTo({ url: '/pages/ai-review/index' })
}
const loadMoreNotes = () => { visibleNoteCount.value += 12 }
const openQuestion = (id: string) => uni.navigateTo({ url: `/pages/practice-session/index?questionId=${encodeURIComponent(id)}&mode=${mode.value === 'favorite' ? 'favorite' : 'wrong'}&returnUrl=${encodeURIComponent(`/pages/practice-tools/index?mode=${mode.value}`)}` })
const back = () => backOrFallback('/pages/practice/index')
</script>

<template>
  <view class="tools-page page safe-top"><view class="tools-top"><button class="back-button" @tap="back"><uni-icons type="back" size="21" color="#4d5c73" /></button><text class="tools-title">学习工具</text><view class="top-space"></view></view><view class="tools-tabs"><view v-for="item in tabLabels" :key="item.key" class="tools-tab" :class="[item.key, { active: mode === item.key }]" :style="{ color: tabColors[item.key] }" @tap="setMode(item.key)"><uni-icons :type="item.icon" size="18" :color="tabColors[item.key]" /><text>{{ item.label }}</text></view></view>
    <view v-if="mode === 'wrong'" class="tools-body">
      <view class="wrong-overview"><view class="wrong-overview-copy"><view><text>{{ questions.length }}</text><text>道错题</text></view><text>答对后自动移出错题本</text></view><view class="wrong-overview-actions"><button class="review-wrong-button" :disabled="!questions.length" @tap="reviewWrongQuestions"><uni-icons type="refresh" size="18" color="#a94e2f" /><text>复习错题</text></button><button class="clear-wrong-button" :disabled="!questions.length" @tap="clearWrongVisible = true"><uni-icons type="trash" size="17" color="#fff" /><text>一键清空</text></button></view></view>
      <view v-if="visibleWrongQuestions.length" class="tool-list wrong-list"><view v-for="item in visibleWrongQuestions" :key="item.id" class="tool-row wrong-row" @tap="openQuestion(item.id)"><view class="row-icon wrong"><uni-icons type="refresh" size="19" color="#e17832" /></view><view class="row-copy wrong-copy"><text class="wrong-title">{{ item.stem }}</text><text class="wrong-meta">{{ item.typeName }} · {{ subjectShortName(item.subjectId) }} · {{ item.knowledgePointTitle }}</text></view><uniIcons type="forward" size="18" color="#a1acba" /></view><view v-if="hasMoreWrongQuestions" class="load-more wrong-load" @tap="loadMoreWrongQuestions">加载更多（剩余 {{ questions.length - visibleWrongCount }} 道）</view><view v-else-if="questions.length > 12" class="load-complete">已展示全部错题</view></view>
      <view v-else class="wrong-empty"><view class="wrong-empty-icon"><uni-icons type="checkmarkempty" size="30" color="#fff" /></view><text>当前没有错题</text><text>答错的题目会自动收录，重新答对后自动移出</text></view>
    </view>
    <view v-else-if="mode === 'favorite'" class="tools-body">
      <view class="favorite-overview"><view class="favorite-overview-head"><view class="favorite-count"><text>{{ favoriteItems.length }}</text><text>条收藏</text></view><button class="manage-button" @tap="manageFavorites = !manageFavorites; selectedFavoriteIds = []">{{ manageFavorites ? '完成' : '批量管理' }}</button></view><scroll-view class="favorite-filters" scroll-x :show-scrollbar="false"><view class="filter-inner"><view v-for="(label, key) in favoriteTypeLabels" :key="key" class="filter-chip" :class="[key, { active: favoriteFilter === key }]" @tap="setFavoriteFilter(key as FavoriteFilter)"><text>{{ label }}</text><text>{{ key === 'all' ? favoriteItems.length : favoriteItems.filter(item => item.type === key).length }}</text></view></view></scroll-view><view v-if="manageFavorites" class="manage-bar"><text @tap="toggleSelectAll">{{ selectedFavoriteIds.length === visibleFavorites.length && visibleFavorites.length ? '取消全选' : '全选当前' }}</text><text>已选 {{ selectedFavoriteIds.length }} 条</text><button @tap="batchRemoveFavorites">取消收藏</button></view></view>
      <view v-if="visibleFavorites.length" class="tool-list favorite-list"><view v-for="item in visibleFavorites" :key="item.id" class="tool-row favorite-row" @tap="openFavorite(item as any)"><view v-if="manageFavorites" class="select-box" :class="{ checked: selectedFavoriteIds.includes(item.id) }"><uni-icons v-if="selectedFavoriteIds.includes(item.id)" type="checkmarkempty" size="16" color="#fff" /></view><view class="row-icon" :style="{ background: `${item.color}16` }"><uniIcons :type="item.icon" size="19" :color="item.color" /></view><view class="row-copy"><text class="item-type" :style="{ color: item.color }">{{ item.typeLabel }}</text><text class="row-title">{{ item.title }}</text><text class="row-meta">{{ item.meta }}</text></view><button v-if="!manageFavorites" class="unfavorite-button" @tap.stop="removeFavorite(item.id)"><uni-icons type="star-filled" size="20" color="#e98a3a" /></button></view><view v-if="hasMoreFavorites" class="load-more" @tap="loadMoreFavorites">加载更多（剩余 {{ filteredFavorites.length - visibleFavoriteCount }} 条）</view><view v-else-if="filteredFavorites.length > 12" class="load-complete">已展示全部收藏</view></view>
      <view v-else class="favorite-empty"><uni-icons type="star" size="29" color="#9ba6b5" /><text>{{ favoriteFilter === 'all' ? '还没有收藏内容' : `还没有收藏的${favoriteTypeLabels[favoriteFilter]}` }}</text><text>收藏的知识点、精讲课和题目会显示在这里</text></view>
    </view>
    <view v-else class="tools-body"><view class="note-overview"><view class="note-overview-head"><view class="note-count"><text>{{ noteItems.length }}</text><text>条笔记</text></view><button class="note-delete-button" @tap="manageNotes = !manageNotes; selectedNoteIds = []">{{ manageNotes ? '完成' : '批量删除' }}</button></view><scroll-view class="note-filters" scroll-x :show-scrollbar="false"><view class="note-filter-inner"><view v-for="(label, key) in noteTypeLabels" :key="key" class="note-filter-chip" :class="{ active: noteFilter === key }" @tap="setNoteFilter(key as NoteFilter)"><text>{{ label }}</text><text>{{ key === 'all' ? noteItems.length : noteItems.filter(item => item.sourceType === key).length }}</text></view></view></scroll-view><view v-if="manageNotes" class="note-manage-bar"><text @tap="toggleSelectAllNotes">{{ selectedNoteIds.length === visibleNotes.length && visibleNotes.length ? '取消全选' : '全选当前' }}</text><text>已选 {{ selectedNoteIds.length }} 条</text><button @tap="requestDeleteNotes">删除笔记</button></view></view><view class="ai-review-entry" @tap="openAiReview"><view class="ai-review-icon"><uni-icons type="paperplane" size="23" color="#fff" /></view><view class="ai-review-copy"><view><text>AI生成复习资料</text></view><text>选择10～30条笔记，由AI整理为复习资料</text></view><view class="ai-review-quota"><text>{{ aiReviewQuota }}</text><text>次可用</text></view><uni-icons type="forward" size="19" color="#789080" /></view><view v-if="visibleNotes.length" class="tool-list note-list"><view v-for="item in visibleNotes" :key="item.id" class="tool-row note-row" @tap="openNoteDetail(item.id)"><view v-if="manageNotes" class="select-box note-select" :class="{ checked: selectedNoteIds.includes(item.id) }"><uni-icons v-if="selectedNoteIds.includes(item.id)" type="checkmarkempty" size="16" color="#fff" /></view><view class="row-icon note"><uniIcons :type="item.icon" size="19" color="#1a9a7b" /></view><view class="row-copy note-copy"><view class="note-type-line"><text>{{ item.typeLabel }}</text><text>{{ new Date(item.updatedAt).toLocaleDateString() }}</text></view><text class="note-title">{{ item.title }}</text><text class="note-preview">{{ item.content }}</text></view><uniIcons v-if="!manageNotes" type="forward" size="18" color="#a1acba" /></view><view v-if="hasMoreNotes" class="load-more note-load" @tap="loadMoreNotes">加载更多（剩余 {{ filteredNotes.length - visibleNoteCount }} 条）</view><view v-else-if="filteredNotes.length > 12" class="load-complete">已展示全部笔记</view></view><view v-else class="note-empty"><uni-icons type="compose" size="30" color="#1a9a7b" /><text>还没有笔记</text><text>在题目、知识点或精讲课中记录后会显示在这里</text></view></view>
    <view v-if="clearWrongVisible" class="cancel-mask" @tap.self="clearWrongVisible = false"><view class="cancel-dialog wrong-dialog" @tap.stop><view class="cancel-mark wrong-mark"><uni-icons type="trash" size="29" color="#fff" /></view><text class="cancel-title">清空错题本</text><text class="cancel-desc">确定清空全部 <text>{{ questions.length }}</text> 道错题吗？清空后这些题目将统一恢复为未做状态。</text><view class="clear-state-tip"><uni-icons type="info" size="17" color="#d47a25" /><text>此操作不会把错题标记为正确</text></view><view class="cancel-actions"><button class="cancel-secondary" @tap="clearWrongVisible = false">暂不清空</button><button class="cancel-primary" @tap="clearWrong">确认清空</button></view></view></view>
    <view v-if="cancelFavoriteVisible" class="cancel-mask" @tap.self="cancelFavoriteVisible = false"><view class="cancel-dialog" @tap.stop><view class="cancel-mark"><uni-icons type="star-filled" size="29" color="#fff" /></view><text class="cancel-title">取消收藏</text><text class="cancel-desc">确定取消选中的 <text>{{ selectedFavoriteIds.length }}</text> 条收藏吗？取消后可在对应内容页重新收藏。</text><view class="cancel-actions"><button class="cancel-secondary" @tap="cancelFavoriteVisible = false">暂不取消</button><button class="cancel-primary" @tap="confirmBatchRemoveFavorites">确认取消</button></view></view></view>
    <view v-if="deleteNotesVisible" class="cancel-mask" @tap.self="deleteNotesVisible = false"><view class="cancel-dialog" @tap.stop><view class="cancel-mark note-delete-mark"><uni-icons type="trash" size="29" color="#fff" /></view><text class="cancel-title">删除笔记</text><text class="cancel-desc">确定删除选中的 <text>{{ selectedNoteIds.length }}</text> 条笔记吗？删除后再次记录将创建新的笔记。</text><view class="cancel-actions"><button class="cancel-secondary" @tap="deleteNotesVisible = false">暂不删除</button><button class="cancel-primary" @tap="confirmDeleteNotes">确认删除</button></view></view></view>
  </view>
</template>

