.tools-page { max-width: 430px; min-height: 100vh; margin: 0 auto; box-sizing: border-box; padding-top: calc(env(safe-area-inset-top) + 18rpx); padding-bottom: 42rpx; background: #f5f7fb; }.tools-top { display: flex; align-items: center; justify-content: space-between; height: 58rpx; }.back-button { width: 58rpx; height: 58rpx; display: flex; align-items: center; justify-content: center; margin: 0; padding: 0; background: #edf1fb; border: 0; border-radius: 15rpx; }.back-button::after { display: none; }.tools-title { color: #1e3048; font-size: var(--sxb-text-title); font-weight: 700; }.top-space { width: 58rpx; }.tools-tabs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8rpx; margin-top: 21rpx; padding: 5rpx; background: #e9eef7; border-radius: 11rpx; }.tools-tab { display: flex; align-items: center; justify-content: center; gap: 5rpx; height: 50rpx; border-radius: 8rpx; font-size: var(--sxb-text-small); font-weight: 700; opacity: .63; }.tools-tab.active { background: #fff; box-shadow: 0 5rpx 13rpx rgba(48,73,124,.1); opacity: 1; }.tools-tab.wrong.active { background: #fff5ed; }.tools-tab.favorite.active { background: #f4f0ff; }.tools-tab.note.active { background: #eaf8f3; }.tools-body { margin-top: 17rpx; }.tool-summary { display: flex; align-items: center; justify-content: space-between; padding: 19rpx; border-radius: 13rpx; }.wrong-summary { background: #fff1eb; border: 1rpx solid #f4ddd1; }.favorite-summary { background: #f1edff; border: 1rpx solid #ded6ff; }.note-summary { background: #edf3ff; border: 1rpx solid #d8e5ff; }.tool-summary>view { display: flex; align-items: baseline; gap: 6rpx; }.summary-number { color: #263953; font-size: var(--sxb-text-heading); font-weight: 700; }.tool-summary>view>text:last-child { color: #65758b; font-size: var(--sxb-text-small); }.summary-desc { max-width: 48%; color: #6f7d91; font-size: var(--sxb-text-meta); line-height: 1.4; text-align: right; }.clear-button { height: 39rpx; display: flex; align-items: center; 